import { InfoOutlined } from '@mui/icons-material';
import { Button, Card, CardActions, CardContent, Divider, Tooltip, Typography } from '@mui/joy';
import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { DirectVestingPicker } from './direct-vesting-picker';
import { FixedApyPicker } from './fixed-apy-picker';
import { ModalProvideRewardPoolForm } from './modal-provide-reward-pool-form';
import { ModalTerminateForm } from './modal-terminate-form';
import { ModalTopUpForm } from './modal-topup-form';
import { VestingPicker } from './vesting-picker';
import { WrappedJettonPicker } from './wrapped-jetton-picker';
import { DEFAULT_DECIMAL_PLACES, TON_DEFAULT_DECIMAL_PLACES } from '/src/constants';
import { useStats } from '/src/hooks/useStats';
import { fromUnits } from '/src/units';
import { friendlyAmount } from '/src/utils';

export const StatsCard = () => {
  const { t } = useTranslation();
  const { address, smctype, staking, directVesting, loading, balance } = useStats();
  const [openTopUp, setOpenTopUp] = useState(false);
  const [openProvideRewardPool, setOpenProvideRewardPool] = useState(false);
  const [openTerminateWindow, setOpenTerminateWindow] = useState(false);

  const tonBalance = useMemo(() => {
    if (!balance) return 0;
    return Number(fromUnits(balance, TON_DEFAULT_DECIMAL_PLACES));
  }, [balance]);
  const rewardPool = useMemo(
    () => Number(fromUnits(staking?.staking?.reward_pool || 0n, DEFAULT_DECIMAL_PLACES)),
    [staking],
  );
  const lockedAmount = useMemo(
    () => Number(fromUnits(directVesting?.locked || 0n, DEFAULT_DECIMAL_PLACES)),
    [directVesting],
  );
  const minimumRewardPool = useMemo(() => {
    if (!staking?.staking || !staking?.value.totalSupply) return 0;

    return Number(
      fromUnits(
        ((staking.value.totalSupply * staking.staking.fixed_apy) / 100n / 365n) *
          BigInt(staking.staking.lockup || 30),
        8,
      ),
    );
  }, [staking]);
  const provideRewardPoolRequired = useMemo(
    () => rewardPool <= minimumRewardPool,
    [rewardPool, minimumRewardPool],
  );
  const topUpRequired = useMemo(() => tonBalance < 10, [tonBalance]);

  let componentMain = <></>;
  switch (smctype) {
    case 'jetton': {
      componentMain = (
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <Typography level="title-lg" mb={2} color="danger">
            Spintria primary jetton information card under maintenance
          </Typography>
        </CardContent>
      );
      break;
    }
    case 'staking': {
      componentMain = (
        <>
          <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
            <Typography level="title-lg" mb={2}>
              {t('staking.card.title')}{' '}
              <Tooltip title={t('staking.form.apy-info')} variant="solid">
                <Typography
                  endDecorator={<InfoOutlined color="secondary" sx={{ width: 18, height: 18 }} />}
                >
                  {t('staking.form.apy')}
                </Typography>
              </Tooltip>
            </Typography>
            <FixedApyPicker />
            {address && (
              <>
                <Divider sx={{ my: 2 }} />
                <Typography level="body-lg" endDecorator="SP">
                  Current reward pool:&nbsp;
                  <Typography color={provideRewardPoolRequired ? 'danger' : 'neutral'}>
                    {staking?.staking?.reward_pool
                      ? friendlyAmount(staking?.staking?.reward_pool)
                      : '0'}
                  </Typography>
                </Typography>
                <Typography level="body-lg" endDecorator="SP">
                  Required reward pool:&nbsp;
                  <Typography color="neutral">{minimumRewardPool.toLocaleString()}</Typography>
                </Typography>
                <Typography level="body-lg" endDecorator="SP">
                  Total staked:&nbsp;
                  <Typography color="neutral">
                    {staking?.value.totalSupply ? friendlyAmount(staking?.value.totalSupply) : '0'}
                  </Typography>
                </Typography>
              </>
            )}
          </CardContent>
          {address && (
            <CardActions buttonFlex="1 1">
              {provideRewardPoolRequired ? (
                <Typography color="danger">
                  Provide minimum: {(minimumRewardPool - rewardPool).toLocaleString()} SP
                </Typography>
              ) : (
                <Typography color="success">Doesn't need to provide reward pool for now</Typography>
              )}
              <Button
                disabled={!staking?.staking}
                variant="soft"
                color="primary"
                onClick={() => setOpenProvideRewardPool(true)}
              >
                Provide Reward pool
              </Button>
            </CardActions>
          )}
        </>
      );
      break;
    }
    case 'vesting': {
      componentMain = (
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <VestingPicker />
        </CardContent>
      );
      break;
    }
    case 'direct-vesting': {
      componentMain = (
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <DirectVestingPicker />
          <Typography level="body-lg" endDecorator="SP">
            Locked amount:&nbsp;
            <Typography color="neutral">{lockedAmount.toLocaleString()}</Typography>
          </Typography>
          <Button
            disabled={!directVesting?.locked}
            variant="soft"
            color="primary"
            onClick={() => setOpenTerminateWindow(true)}
          >
            Terminate contract
          </Button>
        </CardContent>
      );
      break;
    }
    default:
      break;
  }

  const componentBalance = (
    <>
      <Divider sx={{ my: 2 }} />
      {balance ? (
        <Typography
          level="body-lg"
          endDecorator={
            <Typography textColor="neutral.500" level="body-md">
              TON
            </Typography>
          }
        >
          {smctype == 'direct-vesting' ? 'Owner wallet' : ''} Ton balance:&nbsp;
          <Typography color={topUpRequired ? 'danger' : 'neutral'}>
            {tonBalance.toLocaleString() || '?'}
          </Typography>
        </Typography>
      ) : null}
      {address && smctype != 'direct-vesting' && (
        <CardActions buttonFlex="1">
          {balance && topUpRequired ? (
            <Typography color="danger">
              Please topup minimum: {(10 - tonBalance).toFixed(2)} TON
            </Typography>
          ) : (
            <Typography color="success">
              Doesn't need to top up the current smart contract
            </Typography>
          )}
          <Button
            disabled={!staking?.staking}
            variant="soft"
            color="primary"
            onClick={() => setOpenTopUp(true)}
          >
            TopUp
          </Button>
        </CardActions>
      )}
    </>
  );
  return (
    <>
      <Card variant="plain" sx={{ width: '100%' }}>
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <Typography level="title-lg" mb={2}>
            Pick contract type
          </Typography>
          <WrappedJettonPicker />
        </CardContent>
        {smctype && <Divider sx={{ my: 2 }} />}
        {componentMain}
        {componentBalance}
        {smctype === 'staking' ? <></> : smctype === 'vesting' ? <>vesting stuff</> : <></>}
      </Card>
      <ModalTopUpForm open={openTopUp} setOpen={setOpenTopUp} loading={loading} />
      <ModalTerminateForm
        open={openTerminateWindow}
        setOpen={setOpenTerminateWindow}
        loading={loading}
      />
      <ModalProvideRewardPoolForm
        data={staking}
        open={openProvideRewardPool}
        setOpen={setOpenProvideRewardPool}
        loading={loading}
      />
    </>
  );
};
