import { ContractAdapter } from '@ton-api/ton-adapter';
import { TonClient } from '@ton/ton';
import { selector } from 'recoil';
import { tonNetworkTypeAtom } from './ton-network-type-atom';
import { tonApiAdapter } from './tonapi';

export type CustomTonClient = TonClient | ContractAdapter;

export const tonClientSelector = selector<CustomTonClient>({
  key: 'tonClientSelector',
  get: async ({ get }) => {
    const chainType = get(tonNetworkTypeAtom);
    if (!chainType) throw 'chain-type-undefined';
    return Promise.resolve(tonApiAdapter);
    // return orbsTonClient(chainType === CHAIN.MAINNET ? 'mainnet' : 'testnet');
    // return tonCenterTonClient;
  },
});
