import { selectorFamily } from 'recoil';
import { getAddress } from '../../utils';
import { tonApiClient } from './tonapi';

export const tonBalanceSelector = selectorFamily({
  key: 'tonBalanceSelector',
  get:
    ({ address }: { address?: string }) =>
    async () => {
      if (!address) return;
      const accountAddress = getAddress(address);
      if (!accountAddress) return;
      let balance: bigint | undefined = undefined;
      try {
        const acount = await tonApiClient.accounts.getAccount(accountAddress);
        balance = acount.balance;
      } catch (error) {
        console.error(error);
        throw new Error('Failed to retrieve ton balance');
      }
      return balance;
    },
});
