import { atom } from 'recoil';
import { STORAGE_PRICE_DIFF_PICKER_KEY } from '../constants';
import { localStorageEffect } from './effects';

/**
 * 0 - day
 * 1 - week
 * 2 - month
 */
export const priceDiffWatchAtom = atom({
  key: 'priceDiffWatchAtom',
  default: 0,
  effects: [
    localStorageEffect<number>({
      key: STORAGE_PRICE_DIFF_PICKER_KEY,
      isValid: (v) => typeof v === 'number',
      defaultValue: 0,
    }),
  ],
});
