import { useMemo } from 'react';
import { useRecoilValueLoadable } from 'recoil';
import { DEFAULT_DECIMAL_PLACES, MAINNET_SPINTRIA_MASTER_ADDRESS } from '../constants';
import { assetsSelector } from '../state';
import { fromUnits } from '../units';
import { useActiveWallet } from './useActiveWallet';
import { useJettonWallet } from './useJettonWallet';

export function usePrimaryWallet() {
  const { wallet } = useActiveWallet();
  const spintria = useRecoilValueLoadable(assetsSelector(MAINNET_SPINTRIA_MASTER_ADDRESS));
  const jetton = useJettonWallet({
    smc: 'jetton',
    minter: MAINNET_SPINTRIA_MASTER_ADDRESS,
    wallet: wallet?.address,
    balanceTtl: 1e5,
  });
  const friendlyBalance = useMemo(
    () =>
      jetton.state === 'hasValue' && jetton.data
        ? Number(fromUnits(jetton.data.balance.value || 0n, DEFAULT_DECIMAL_PLACES))
        : 0,
    [jetton],
  );
  const showSkeleton = useMemo(() => !jetton && spintria.state === 'loading', [jetton, spintria]);

  return {
    wallet,
    jetton,
    spintria: spintria.state === 'hasValue' && spintria.contents ? spintria.contents : undefined,
    friendlyBalance,
    loading: spintria.state === 'loading' || jetton.state === 'loading',
    jettonPending: jetton.pending,
    showSkeleton,
  };
}
