import { Check } from '@mui/icons-material';
import { Chip, Radio, RadioGroup } from '@mui/joy';
import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router';
import { RouteParams, SmcType, smcTypes } from '/src/types';

export const WrappedJettonPicker = () => {
  const { smctype, root } = useParams<RouteParams>();
  const [smc, setSmc] = useState<SmcType>();
  const navigate = useNavigate();

  useEffect(() => {
    setSmc(smcTypes.indexOf(smctype || 'staking') !== -1 ? smctype : 'staking');
  }, [smctype]);

  return (
    <RadioGroup name="fixed-apy" orientation="horizontal" sx={{ flexWrap: 'wrap', gap: 2 }}>
      {smcTypes.map((name) => {
        const checked = smc === name;
        return (
          <Chip
            key={name}
            variant="soft"
            sx={{ px: { sm: 2 }, py: { sm: 0.75 } }}
            color={checked ? 'primary' : 'neutral'}
            startDecorator={checked && <Check sx={{ zIndex: 1, pointerEvents: 'none' }} />}
          >
            <Radio
              variant="outlined"
              color={checked ? 'primary' : 'neutral'}
              disableIcon
              overlay
              label={name}
              value={name}
              checked={checked}
              onChange={(event) => {
                if (event.target.checked) {
                  navigate(`${root ? `/${root}/` : '/'}stats/${name}`, {
                    replace: true,
                  });
                }
              }}
            />
          </Chip>
        );
      })}
    </RadioGroup>
  );
};
