import { useParams } from 'react-router';
import { useRecoilValueLoadable } from 'recoil';
import {
  WalletEventManager,
  assetsSelector,
  directVestingByAddress,
  tonBalanceSelector,
} from '../state';
import { RouteParams, WalletEventType } from '../types';
import { useInterval } from './useInterval';

export function useStats() {
  const { address, smctype } = useParams<RouteParams>();
  const staking = useRecoilValueLoadable(
    assetsSelector(smctype != 'direct-vesting' ? address : undefined),
  );
  const directVesting = useRecoilValueLoadable(directVestingByAddress(address));
  const tonBalance = useRecoilValueLoadable(tonBalanceSelector({ address }));

  useInterval(
    () => {
      if (address && smctype) {
        WalletEventManager.publish(WalletEventType.RefetchAssets, { address, smcType: smctype });
      }
    },
    smctype && address ? 2e4 : null,
  );

  return {
    address,
    smctype,
    staking: staking.state === 'hasValue' && staking.contents ? staking.contents : undefined,
    directVesting:
      directVesting.state === 'hasValue' && directVesting.contents
        ? directVesting.contents
        : undefined,
    loading: staking.state === 'loading' || tonBalance.state === 'loading',
    balance:
      tonBalance.state === 'hasValue' && tonBalance.contents ? tonBalance.contents : undefined,
  };
}
