import { Add, Visibility } from '@mui/icons-material';
import { Box, Button, IconButton, Stack, Table, Tooltip, Typography } from '@mui/joy';
import throttle from 'lodash.throttle';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useRecoilState, useRecoilValue, useRecoilValueLoadable, useSetRecoilState } from 'recoil';
import {
  MAINNET_SPINTRIA_MASTER_ADDRESS,
  NUMBER_COMPACT_TRIGGER_VALUE,
  STALE_OPACITY,
} from '/src/constants';
import {
  activeWalletSelector,
  addWalletModalAtom,
  currencyAtom,
  directVestingSelector,
  jettonsAtom,
  priceDiffWatchAtom,
  ratesSelector,
} from '/src/state';
import { appCurrencies } from '/src/types';
import { fromUnits } from '/src/units';

export const TotalBalance = () => {
  const { t } = useTranslation();
  const rates = useRecoilValueLoadable(ratesSelector({ address: MAINNET_SPINTRIA_MASTER_ADDRESS }));
  const wallet = useRecoilValueLoadable(activeWalletSelector);
  const [diffWatch, setDiffWatch] = useRecoilState(priceDiffWatchAtom);
  const currency = useRecoilValue(currencyAtom);
  const jettons = useRecoilValueLoadable(jettonsAtom);
  const vesting = useRecoilValueLoadable(directVestingSelector);
  const [totalBalance, setTotalBalance] = useState<number>();
  const [loading, setLoading] = useState(true);
  const throttleLoading = useCallback(throttle(setLoading, 1e3, { trailing: true }), []);
  const [openRatesDiff, setOpenRatesDiff] = useState(false);
  const setOpenAddWallet = useSetRecoilState(addWalletModalAtom);

  useEffect(() => {
    throttleLoading(
      rates.state == 'loading' ||
        wallet.state == 'loading' ||
        vesting.state == 'loading' ||
        jettons.state == 'loading' ||
        (jettons.state == 'hasValue' && !!jettons.contents?.stale),
    );
  }, [rates.state, wallet.state, vesting.state, jettons]);

  useEffect(() => {
    let vestingLocked = 0;
    if (vesting.state == 'hasValue' && vesting.contents) {
      vestingLocked =
        vesting.contents.data.totalDeposited - vesting.contents.data.totalWithdrawals > 0
          ? Number(fromUnits(vesting.contents.locked, 8))
          : 0;
    }
    if (jettons.state === 'hasValue' && jettons.contents) {
      setTotalBalance(
        vestingLocked +
          jettons.contents.data.balances
            .map((m) => fromUnits(m.balance, m.jetton.decimals))
            .map(Number)
            .reduce((a, b) => (a += b), 0),
      );
    }
  }, [jettons, vesting]);

  const balanceRate = useMemo(() => {
    if (
      totalBalance &&
      rates.state === 'hasValue' &&
      rates.contents &&
      rates.contents.prices &&
      rates.contents.prices[currency]
    ) {
      const rate = rates.contents.prices[currency];
      let diff: string | undefined;
      switch (diffWatch) {
        case 0:
          diff = rates.contents.diff24h ? rates.contents.diff24h[currency] : undefined;
          break;
        case 1:
          diff = rates.contents.diff7d ? rates.contents.diff7d[currency] : undefined;
          break;
        case 2:
          diff = rates.contents.diff30d ? rates.contents.diff30d[currency] : undefined;
          break;
        default:
          break;
      }
      return {
        rate,
        value: rate * totalBalance,
        diffTooltip: diff ? (
          <Tooltip
            open={openRatesDiff}
            variant="outlined"
            arrow
            title={
              <Box
                sx={{
                  display: 'flex',
                  flexDirection: 'column',
                  maxWidth: 200,
                  justifyContent: 'center',
                  p: 0,
                }}
              >
                <Table size="md">
                  <thead>
                    <tr>
                      <th style={{ width: '40%' }}>{t('rates.period')}</th>
                      <th colSpan={2}>{t('rates.change')}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {renderDiffRow(
                      t('rates.day'),
                      rates.contents.diff24h ? rates.contents.diff24h[currency] : '',
                      diffWatch === 0,
                      () => setDiffWatch(0),
                    )}
                    {renderDiffRow(
                      t('rates.week'),
                      rates.contents.diff7d ? rates.contents.diff7d[currency] : '',
                      diffWatch === 1,
                      () => setDiffWatch(1),
                    )}
                    {renderDiffRow(
                      t('rates.month'),
                      rates.contents.diff30d ? rates.contents.diff30d[currency] : '',
                      diffWatch === 2,
                      () => setDiffWatch(2),
                    )}
                  </tbody>
                </Table>
              </Box>
            }
          >
            <Typography
              sx={{ borderBottom: '1px dashed' }}
              color={diff.startsWith('−') ? 'danger' : 'success'}
            >
              {diff}
            </Typography>
          </Tooltip>
        ) : null,
      };
    }
  }, [rates, totalBalance, currency, openRatesDiff, diffWatch]);

  return (
    <Stack direction="column" alignItems="center">
      {wallet.state == 'hasValue' && wallet.contents ? (
        <Box
          display="flex"
          flexDirection="column"
          alignItems="center"
          sx={[loading ? { opacity: STALE_OPACITY } : {}]}
          className={loading ? '' : 'fade-out'}
        >
          <Typography level="body-md">{t('jetton.balance')}</Typography>
          <Typography
            level="h1"
            sx={{
              fontSize: '275%',
              position: 'relative',
              overflow: 'hidden',
            }}
            noWrap
            endDecorator={
              <Typography sx={{ color: '#8885', marginInlineStart: -0.75 }}>{'SP'}</Typography>
            }
          >
            {totalBalance?.toLocaleString(undefined, {
              notation: totalBalance > NUMBER_COMPACT_TRIGGER_VALUE ? 'compact' : 'standard',
              maximumFractionDigits: 2,
            }) || '0'}
          </Typography>
          <Typography
            level="body-md"
            sx={{ color: '#888c' }}
            slotProps={{
              root: {
                onClick: () => setOpenRatesDiff(!openRatesDiff),
                // onPointerEnter: () => setOpenRatesDiff(!openRatesDiff),
                // onPointerLeave: () => setOpenRatesDiff(!openRatesDiff),
              },
            }}
            endDecorator={balanceRate?.diffTooltip}
          >
            {appCurrencies[currency].symbol}
            {balanceRate?.value.toLocaleString(undefined, {
              maximumFractionDigits: 2,
            }) || '0'}
            &nbsp;&nbsp;
          </Typography>
        </Box>
      ) : (
        <Stack gap={3}>
          <Typography level="body-sm" sx={{ maxWidth: { xs: 'auto', md: '40vw' } }}>
            {t('wallets.to-continue')}
          </Typography>
          <Button startDecorator={<Add />} onClick={() => setOpenAddWallet(true)}>
            {t('wallets.add-wallet')}
          </Button>
        </Stack>
      )}
    </Stack>
  );
};

const renderDiffRow = (label: string, diff: string, isWatched: boolean, onClick: () => void) => (
  <tr>
    <td>{label}</td>
    <td>
      <Typography noWrap color={diff?.startsWith('−') ? 'danger' : 'success'}>
        {diff}
      </Typography>
    </td>
    <td align="right">
      {isWatched ? null : (
        <IconButton sx={{ p: 0 }} onClick={onClick}>
          <Visibility sx={{ width: 24, height: 24 }} />
        </IconButton>
      )}
    </td>
  </tr>
);
