import { biometry, isTMA, on } from '@telegram-apps/sdk-react';

export class BiometryTokenStorage<T> {
  private _mounting = false;
  private _mounted = false;
  private _granted = false;
  private _needToOpenSettings = false;
  private _requestingAccess = false;
  private _value?: T;
  private _abortController?: AbortController;
  private _removeEventListener?: VoidFunction;

  constructor() {
    this.mount();
    /**
     * available	[boolean]	Shows whether biometry is available.
     * access_requested	[boolean]	Shows whether permission to use biometrics has been requested.
     * access_granted	[boolean]	Shows whether permission to use biometrics has been granted.
     * device_id	[string]	A unique device identifier that can be used to match the token to the device.
     * token_saved	[boolean]	Show whether local BiometryTokenStorage contains previously saved token.
     * type	[string]	The type of biometrics currently available on the device. Possible values: face or finger.
     */
    this._removeEventListener = on('biometry_info_received', (info) => console.log(info));
  }

  public get value() {
    return this._value;
  }

  public get mounted() {
    return this._mounted;
  }

  public get mounting() {
    return this._mounting;
  }

  public get granted() {
    return this._granted;
  }

  public get needToOpenSettings() {
    return this._needToOpenSettings;
  }

  public get requestingAccess() {
    return this._requestingAccess;
  }

  async mount() {
    if (!isTMA()) {
      throw Error('storage is not under TMA');
    }
    if (!biometry.isSupported()) {
      throw Error('storage is not supported');
    }
    if (!biometry.mount.isAvailable()) {
      throw Error('storage mount is not vailable');
    }
    this._mounted = biometry.isMounted();
    if (this._mounting || this._mounted) {
      return;
    }
    if (this._abortController) {
      this._abortController.abort();
    }
    this._abortController = new AbortController();
    try {
      this._mounting = true;
      await biometry.mount(this._abortController.signal);
      this._mounting = false;
      this._mounted = biometry.isMounted();
    } catch (err) {
      throw Error(
        biometry.mountError() == err
          ? 'BiometryTokenStorage mount error'
          : 'unspecified BiometryTokenStorage error',
      );
    }
  }

  async requestAccess() {
    if (this._requestingAccess || this._mounting || !this._mounted) {
      return;
    }
    if (!biometry.requestAccess.isAvailable()) {
      throw Error('BiometryTokenStorage request access is not available');
    }
    this._requestingAccess = true;
    this._granted = await biometry.requestAccess();
    this._needToOpenSettings = !this._granted;
    this._requestingAccess = false;
  }

  openSettings() {
    if (this._granted) return;
    if (!biometry.openSettings.isAvailable()) {
      throw Error('BiometryTokenStorage openSettings is not available');
    }
    biometry.openSettings();
  }

  async get(reason = 'Authenticate access to storage') {
    if (!biometry.authenticate.isAvailable()) {
      throw Error('BiometryTokenStorage authenticate is not available');
    }
    const { status, token } = await biometry.authenticate({ reason });
    if (status === 'authorized' && token?.length) {
      return this.unpackStorage(token);
    }
  }

  unpackStorage(value: string) {
    try {
      const parsed = JSON.parse(value);
      if (parsed) return parsed as T;
    } catch (error) {
      throw new Error('Failed to retrieve value from storage');
    }
  }

  /**
   * @param value 0-1024 length
   * @param reason to update sorage
   * @returns update response
   */
  async set(value?: T, reason = 'Want to delete storage') {
    if (!biometry.updateToken.isAvailable()) {
      throw Error('BiometryTokenStorage authenticate is not available');
    }
    try {
      const response = await biometry.updateToken({ reason, token: JSON.stringify(value) });
      if (response == 'updated') {
        return response;
      }
    } catch (err) {
      throw Error('BiometryTokenStorage update error');
    }
  }

  async remove() {
    return this.set();
  }

  destroy() {
    this._removeEventListener?.();
  }
}
