import { Navigate, Route, RouteObject, RouterProvider, Routes } from 'react-router-dom';
import { TelegramRouter } from './telegram-router';
import {
  FaucetScreen,
  JettonScreen,
  MainScreen,
  SendScreen,
  Stats,
  StyledCircularProgress,
  SwapScreen,
} from '/src/components';

import { useEffect, useMemo } from 'react';
import { createBrowserRouter } from 'react-router-dom';
import { useRecoilState, useRecoilValueLoadable, useSetRecoilState } from 'recoil';
import { appUidAtom, metricsAtom, tmaLaunchParamsSelector } from '../state';
import { isUnderTelegramWebview, uuidv4 } from '../utils';
import { OpenMiniApp } from './open-mini-app';

const spintriaRoutes = ({ tma = false }): RouteObject[] => {
  const res = [
    { path: '/', index: true, element: <MainScreen /> },
    { path: '/jetton/:address', element: <JettonScreen /> },
    { path: '/jetton', element: <JettonScreen /> },
    { path: '/swap', element: <SwapScreen /> },
    { path: '/send', element: <SendScreen /> },
    { path: '/stats/:smctype/:address', element: <Stats /> },
    { path: '/stats/:smctype', element: <Stats /> },
    { path: '/stats', element: <Stats /> },
  ];
  // { path: '/pizza', element: <PizzaScreen /> },
  if (tma) {
    res.push({ path: '/faucet', element: <FaucetScreen /> });
  }
  return res;
};
const WalletBrowserRouter = () => {
  const [appUid, setAppUid] = useRecoilState(appUidAtom);
  const setMetrics = useSetRecoilState(metricsAtom);

  useEffect(() => {
    if (appUid) return;
    setAppUid(uuidv4());
  }, [appUid, setAppUid]);

  useEffect(() => {
    if (!appUid) return;
    setMetrics((v) => ({ ...v, deeplink: 'web-direct', user: appUid }));
  }, [appUid]);

  return <RouterProvider router={createBrowserRouter(spintriaRoutes({}))} />;
};

export const WalletRouter = () => {
  const { state, contents } = useRecoilValueLoadable(tmaLaunchParamsSelector);
  const isUnderTma = useMemo(
    () => state == 'hasValue' && typeof contents?.tgWebAppData?.user?.id == 'number',
    [state, contents],
  );
  const isJustUnderTelegramWebview = !isUnderTma && isUnderTelegramWebview;
  return state == 'loading' ? (
    <StyledCircularProgress thickness={3} />
  ) : isUnderTma ? (
    <TelegramRouter>
      <Routes>
        {spintriaRoutes({ tma: true }).map((m) => (
          <Route key={`wallet-route-${m.path}`} path={m.path} index={m.index} element={m.element} />
        ))}
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </TelegramRouter>
  ) : isJustUnderTelegramWebview ? (
    <OpenMiniApp />
  ) : (
    <WalletBrowserRouter />
  );
};
