import { ColorPaletteProp, VariantProp } from '@mui/joy';
import { JettonsBalances, TokenRates } from '@ton-api/client';
import { Address, Cell } from '@ton/core';

type Modify<T, R> = Omit<T, keyof R> & R;

export const appLanguages = ['en', 'ru'] as const;
export const appCurrencies = {
  USD: { name: 'USD', symbol: '$' },
  RUB: { name: 'RUB', symbol: '₽' },
} as const;
export type Currency = keyof typeof appCurrencies;
export function instanceOfCurrency(o: unknown): o is Currency {
  return !!o && typeof o === 'string' && Object.keys(appCurrencies).indexOf(o) !== -1;
}

export const smcTypes = ['jetton', 'staking', 'vesting', 'direct-vesting'] as const;
export type SmcType = (typeof smcTypes)[number];

export type RouteParams = {
  root?: string;
  address?: string;
  smctype?: SmcType;
};

export interface JettonMetadata {
  name: string;
  symbol: string;
  description?: string;
  decimals?: number | string;
  image?: string;
  image_data?: string;
  uri?: string;
}

export type JettonData = {
  totalSupply: bigint;
  mintable: boolean;
  adminAddress: Address;
  content: Cell;
  walletCode: Cell;
};

export type JettonWithMetadata = Modify<JettonData, { content: JettonMetadata | undefined }>;
export type LightJettonWithMetadata = Modify<
  Omit<JettonData, 'mintable' | 'adminAddress' | 'walletCode'>,
  { content: JettonMetadata | undefined }
>;

export type VestingData = {
  totalDeposited: bigint;
  startTime: number;
  totalDuration: number;
  unlockPeriod: number;
  cliffDuration: number;
};

export type StakingParams = {
  lockup: number;
  min_stake: bigint;
  max_stake: bigint;
  max_total: bigint;
  reward_pool: bigint;
  fixed_apy: bigint;
};
export function instanceOfJettonData(o: unknown): o is JettonData {
  return (
    !!o &&
    typeof o === 'object' &&
    'totalSupply' in o &&
    'mintable' in o &&
    'adminAddress' in o &&
    'content' in o &&
    'walletCode' in o
  );
}

export const instanceOfJettonWithMetadata = instanceOfJettonData;

export function instanceOfJettonMetadata(o: unknown): o is JettonMetadata {
  return !!o && typeof o === 'object' && 'name' in o && 'symbol' in o && 'image' in o;
}

export function instanceOfVestingData(o: unknown): o is VestingData {
  return (
    !!o &&
    typeof o === 'object' &&
    'totalDeposited' in o &&
    'startTime' in o &&
    'totalDuration' in o &&
    'unlockPeriod' in o &&
    'cliffDuration' in o
  );
}

export function instanceOfStakingData(o: unknown): o is StakingParams {
  return (
    !!o &&
    typeof o === 'object' &&
    'lockup' in o &&
    'min_stake' in o &&
    'max_stake' in o &&
    'max_total' in o &&
    'reward_pool' in o &&
    'fixed_apy' in o
  );
}

export interface CancellablePromise<T> extends Promise<T> {
  cancel: () => void;
}

export type TotalValueLocked = {
  type: 'staking' | 'vesting';
  value: bigint;
  timestamp: number;
};

export function instanceOfTotalValueLocked(o: unknown): o is TotalValueLocked {
  return !!o && typeof o === 'object' && 'type' in o && 'value' in o && 'timestamp' in o;
}

export function instanceOfTotalValueLockedArray(o: any): o is TotalValueLocked[] {
  return o && Array.isArray(o) && o.every(instanceOfTotalValueLocked);
}

export type Asset = {
  address: string;
  smc: SmcType;
  value: LightJettonWithMetadata;
  staking?: StakingParams;
  vesting?: VestingData;
  timestamp: number;
};

export function instanceOfAsset(o: unknown): o is Asset {
  return !!o && typeof o === 'object' && 'address' in o && 'value' in o && 'timestamp' in o;
}

export type TonApiRates = { timestamp: number; rates: Record<string, TokenRates> };

export function instanceOfJettonRates(o: unknown): o is TonApiRates {
  return !!o && typeof o === 'object' && 'timestamp' in o && 'rates' in o;
}

export function instanceOfAssetArray(o: any): o is Asset[] {
  return o && Array.isArray(o) && o.every(instanceOfAsset);
}

export type ExtendedWalletBalance = {
  value: bigint;
  deposit?: bigint;
  stakeAt?: number;
  timestamp: number;
};

export type JettonWalletItem = {
  smc: SmcType;
  wallet: string;
  minter: string;
  jetton: string;
  balance: ExtendedWalletBalance;
};

export function instanceOfJettonWalletItem(o: unknown): o is JettonWalletItem {
  return (
    !!o &&
    typeof o === 'object' &&
    'wallet' in o &&
    'minter' in o &&
    'jetton' in o &&
    'balance' in o
  );
}

export function instanceOfJettonWalletItemArray(o: any): o is JettonWalletItem[] {
  return o && Array.isArray(o) && o.every(instanceOfJettonWalletItem);
}

export type SnackData<T = any> = {
  id: string;
  timestamp: number;
  variant?: VariantProp;
  color?: ColorPaletteProp;
  autoHideDuration?: number | null;
  title: string;
  body?: string;
  data?: T;
};

export type JettonWalletData = {
  address: Address | undefined;
  owner: Address | undefined;
  minter: Address | undefined;
  balance: bigint | undefined;
  stakeAt: number | undefined;
};
export enum WalletEventType {
  RefetchAssets = 'refetch-assets',
  RefetchRates = 'refetch-rates',
  RefetchBalances = 'refetch-balances',
}
export type WalletEventDetail = {
  smcType: SmcType;
  address: string;
};
export type FileUploaderEvent = CustomEvent<WalletEventDetail>;
export function isCustomEvent(event: Event): event is CustomEvent {
  return 'detail' in event;
}
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function isWalletEventDetail(o: any): o is WalletEventDetail {
  return o && 'address' in o && 'smcType' in o;
}

export type WalletJettonsBalances = {
  wallet: string;
  data: JettonsBalances;
  timestamp: number;
  stale?: boolean;
};

export function instanceOfWalletJettonsBalances(o: unknown): o is WalletJettonsBalances {
  return !!o && typeof o === 'object' && 'wallet' in o && 'data' in o;
}

export enum TvlType {
  none = 'none',
  total = 'total',
  presale = 'presale',
  staking6 = 'staking6',
  staking9 = 'staking9',
  staking12 = 'staking12',
  staking15 = 'staking15',
  staking18 = 'staking18',
  vesting1607 = 'vesting1607',
  vestingAinz = 'vestingAinz',
}

export type TvlResponse = {
  tvlType: TvlType;
  value: number;
};
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function isTvlResponse(o: any): o is TvlResponse {
  return o && 'tvlType' in o && 'value' in o;
}

export type FaucetInvoiceResponse = { invoice: string };
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function isFaucetInvoiceResponse(o: any): o is FaucetInvoiceResponse {
  return o && 'invoice' in o;
}

export type OpenedInvoiceResponse = {
  status: string;
  userId: number;
  wallet: string;
  id: string;
  createdAt: Date;
};
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function isOpenedInvoiceResponse(o: any): o is OpenedInvoiceResponse {
  return o && 'id' in o;
}

export enum WalletType {
  tcsdk = 'tcsdk', // TON Connect SDK
  bip39 = 'bip39',
}

export type WalletItem = {
  address: string;
  // phrase: string;
  name: string;
  wallet: WalletType;
  active: boolean;
};

export function isWalletItem(o: any): o is WalletItem {
  return o && 'address' in o && 'active' in o && 'wallet' in o;
}

export function isWalletItems(o: any): o is WalletItem[] {
  return o && Array.isArray(o) && o.every(isWalletItem);
}
