import { Wallet } from '@mui/icons-material';
import { Snackbar } from '@mui/joy';
import { params as ymParams } from 'lyam';
import { PropsWithChildren, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useRecoilCallback, useRecoilState, useRecoilValueLoadable } from 'recoil';
import { YANDEX_METRICA_COUNTER_ID } from '../constants';
import { useResetTonconnectBug } from '../hooks';
import {
  activeWalletSelector,
  assetsAtom,
  jettonsAtom,
  jettonWalletsAtom,
  metricsAtom,
  snacksAtom,
  transformMetricsToYandex,
} from '../state';
import { getAddress } from '../utils';

export const App = ({ children }: PropsWithChildren) => {
  useResetTonconnectBug();
  const { t } = useTranslation();

  const [openSnackWalletConnected, setOpenSnackWalletConnected] = useState(false);
  const activeWallet = useRecoilValueLoadable(activeWalletSelector);
  const resetTonWalletData = useRecoilCallback(
    ({ set, reset }) =>
      () => {
        set(jettonWalletsAtom, []);
        set(snacksAtom, []);
        set(assetsAtom, []);
        reset(jettonsAtom);
      },
    [],
  );
  const [metrics, setMetrics] = useRecoilState(metricsAtom);

  useEffect(() => {
    if (activeWallet.state == 'hasValue') {
      if (activeWallet.contents) {
        const wallet = getAddress(activeWallet.contents.address);
        if (wallet) {
          setMetrics((v) => ({ ...v, wallet: wallet.toString() }));
        }
        setOpenSnackWalletConnected(true);
      } else {
        resetTonWalletData();
      }
    }
  }, [activeWallet]);

  useEffect(() => {
    if (!metrics || import.meta.env.DEV) return;
    const params = transformMetricsToYandex(metrics);
    if (params) {
      ymParams(YANDEX_METRICA_COUNTER_ID.toString(), params);
    }
  }, [metrics]);

  return (
    <>
      {children}
      <Snackbar
        variant="soft"
        color="neutral"
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        open={openSnackWalletConnected}
        onClose={() => setOpenSnackWalletConnected(false)}
        autoHideDuration={3e3}
        startDecorator={<Wallet sx={{ color: '#8888' }} />}
        size="lg"
        sx={{ p: 1.5, minWidth: 200 }}
      >
        {activeWallet.contents?.name} {t('connected')}
      </Snackbar>
    </>
  );
};
