import { atom } from 'recoil';
import { STORAGE_CURRENCY_KEY } from '../constants';
import { Currency, instanceOfCurrency } from '../types';
import { localStorageEffect } from './effects';

export const currencyAtom = atom({
  key: 'currencyAtom',
  effects: [
    localStorageEffect<Currency>({
      key: STORAGE_CURRENCY_KEY,
      isValid: instanceOfCurrency,
      defaultValue: 'USD',
    }),
  ],
});
