import { Address, toNano } from '@ton/core';
import { useState } from 'react';
import { useResetRecoilState, useSetRecoilState } from 'recoil';
import { DEFAULT_DECIMAL_PLACES } from '../constants';
import { JettonWallet } from '../contracts/JettonWallet';
import { refreshDelayAtom, tonClientSelector } from '../state';
import { JettonWalletItem } from '../types';
import { toUnits } from '../units';
import { delay, waitForSeqno } from '../utils';
import { useLoadable } from './useLoadable';
import { useTonConnect } from './useTonConnect';

export function useWithdrawStake(jetton?: JettonWalletItem) {
  const setRefreshDelay = useSetRecoilState(refreshDelayAtom);
  const resetRefreshDelay = useResetRecoilState(refreshDelayAtom);
  const [amount, setAmount] = useState('');
  const { sender, wallet } = useTonConnect();
  const [sendingTx, setSendingTx] = useState(false);
  const [closeForm, setCloseForm] = useState(false);
  const client = useLoadable(tonClientSelector);

  return {
    amount,
    setAmount,
    sendingTx,
    closeForm,
    sendWithdraw: async () => {
      if (!client || !wallet || !jetton) {
        return;
      }
      const decimals = DEFAULT_DECIMAL_PLACES;
      const jettonAmount = toUnits(amount, decimals);

      setRefreshDelay(null);
      setSendingTx(true);

      const jettonWalletAddress = Address.parse(jetton.jetton);
      if (!jettonWalletAddress) {
        return;
      }
      const waiter = await waitForSeqno(client, Address.parse(wallet));
      let senderFail = false;
      try {
        await sender?.send({
          to: jettonWalletAddress,
          value: toNano(0.06),
          body: JettonWallet.burnMessage(jettonAmount, sender.address!, null),
        });
      } catch (error) {
        senderFail = true;
      }

      if (senderFail) {
        resetRefreshDelay();
        setSendingTx(false);
        return;
      }

      try {
        await waiter();
        await delay(10 * 1000);
      } catch (error) {}

      resetRefreshDelay();
      setSendingTx(false);
      setCloseForm(true);
      setAmount('');
    },
  };
}
