import { Address, toNano } from '@ton/core';
import { useState } from 'react';
import { useParams } from 'react-router';
import { useResetRecoilState, useSetRecoilState } from 'recoil';
import { DirectVestingContract } from '../contracts';
import { directVestingSelector, refreshDelayAtom, tonClientSelector } from '../state';
import { RouteParams } from '../types';
import { delay, getAddress, waitForSeqno } from '../utils';
import { useLoadable } from './useLoadable';
import { useTonConnect } from './useTonConnect';

export function useWithdrawDirectVesting() {
  const { address } = useParams<RouteParams>();
  const resetData = useResetRecoilState(directVestingSelector);
  const setRefreshDelay = useSetRecoilState(refreshDelayAtom);
  const resetRefreshDelay = useResetRecoilState(refreshDelayAtom);
  const { sender, wallet } = useTonConnect();
  const [sendingTx, setSendingTx] = useState(false);
  const [closeForm, setCloseForm] = useState(false);
  const client = useLoadable(tonClientSelector);

  return {
    sendingTx,
    closeForm,
    sendWithdraw: async () => {
      if (!client || !wallet || !address) {
        return;
      }
      const vestingAddress = getAddress(address);
      if (!vestingAddress) {
        return;
      }
      setRefreshDelay(null);
      setSendingTx(true);

      const waiter = await waitForSeqno(client, Address.parse(wallet));
      let senderFail = false;
      try {
        await sender?.send({
          to: vestingAddress,
          value: toNano(0.1),
          body: DirectVestingContract.withdrawMessage(),
        });
      } catch (error) {
        senderFail = true;
      }

      if (senderFail) {
        resetRefreshDelay();
        setSendingTx(false);
        return;
      }

      try {
        await waiter();
        await delay(10 * 1000);
      } catch (error) {}

      resetRefreshDelay();
      resetData();
      setSendingTx(false);
      setCloseForm(true);
    },
  };
}
