// Wrapper around JSON stringify/parse methods to support bigint serialization

import { Address } from '@ton/core';

export function jsonReplacer(key: string, value: any) {
  if (typeof value === 'bigint') {
    return {
      __type: 'bigint',
      __value: value.toString(),
    };
  } else if (value instanceof Address) {
    return {
      __type: 'ton-address',
      __value: value.toRawString(),
    };
  } else {
    return value;
  }
}

export function jsonReviver(key: string, value: any) {
  if (value && value.__type == 'bigint') {
    return BigInt(value.__value);
  }
  if (value && value.__type == 'ton-address') {
    return Address.parseRaw(value.__value);
  }
  return value;
}
