import { NotificationsNone } from '@mui/icons-material';
import { Badge, IconButton } from '@mui/joy';
import { useState } from 'react';
import { useRecoilValue } from 'recoil';
import { snacksAtom } from '../state';
import { ModalSnacks } from './modal-snacks';

export const SnacksButton = () => {
  const notifications = useRecoilValue(snacksAtom);
  const [open, setOpen] = useState(false);
  const disabled = notifications.length === 0;

  return (
    <>
      {!disabled && (
        <IconButton
          aria-controls={'composition-menu'}
          aria-haspopup="true"
          aria-expanded={open ? 'true' : undefined}
          disabled={disabled}
          onClick={() => setOpen(!open)}
        >
          <Badge
            invisible={disabled}
            badgeInset="5%"
            color="danger"
            variant="solid"
            size="sm"
            slotProps={{ badge: { sx: { boxShadow: 'unset' } } }}
          >
            <NotificationsNone />
          </Badge>
        </IconButton>
      )}
      <ModalSnacks data={notifications} open={open} setOpen={setOpen} />
    </>
  );
};
