import { DarkModeRounded, LightMode, PersonalVideo } from '@mui/icons-material';
import { IconButton, IconButtonProps, useColorScheme } from '@mui/joy';
import { useEffect, useMemo, useState } from 'react';

export default function ColorSchemeToggle(props: IconButtonProps) {
  const { onClick, sx, ...other } = props;
  const { mode, setMode } = useColorScheme();
  const [mounted, setMounted] = useState(false);
  const ModeIcon = useMemo(
    () =>
      mode === 'dark' ? <LightMode /> : mode === 'light' ? <PersonalVideo /> : <DarkModeRounded />,
    [mode],
  );

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return <IconButton size="sm" variant="outlined" color="neutral" {...other} sx={sx} disabled />;
  }
  return (
    <IconButton
      id="toggle-mode"
      size="sm"
      variant="soft"
      color="neutral"
      {...other}
      onClick={(event) => {
        setMode(mode === 'dark' ? 'light' : mode === 'light' ? 'system' : 'dark');
        onClick?.(event);
      }}
    >
      {ModeIcon}
    </IconButton>
  );
}
